def branded_home(request):
    brand=brand_for_request(request)
    if brand:return render(request,brand.template,{"brand":brand})
    return services(request)
def branded_product(request, pk):
    brand=brand_for_request(request)
    if not brand or brand.code!="mojplaywin": raise Http404
    product=get_object_or_404(Product, pk=pk, active=True)
    summary = (product.metadata or {}).get("summary") if isinstance(product.metadata, dict) else None
    schema = {"@context":"https://schema.org", "@type":"Product", "name":product.title,
              "url":f"https://mojplaywin.com/store/product/{product.pk}/",
              "description":str(summary or "Digital product listed in the MojPlayWin catalog.")}
    # Do not publish Offer/availability/payment claims until checkout is verified.
    product_schema_json = json.dumps(schema, ensure_ascii=False).replace("<", "\\u003c")
    return render(request,"brands/mojplaywin/product.html",{"brand":brand,"product":product,"product_schema_json":product_schema_json})

def branded_store(request):
    brand=brand_for_request(request)
    if not brand or brand.code!="mojplaywin": raise Http404
    try:
        products=list(Product.objects.filter(active=True).order_by("-id"))
    except Exception:
        products=[]
    return render(request,"brands/mojplaywin/store.html",{"brand":brand,"products":products})

def branded_page(request, page):
    brand=brand_for_request(request)
    if not brand or brand.code!="mojplaywin": raise Http404
    data=PAGES.get(page) or FACTORY_CATALOG.get(page) or CORPORATE_FUTURE.get(page)
    if not data: raise Http404
    return render(request,"brands/mojplaywin/page.html",{"brand":brand,"page":data,"page_key":page})
def branded_venture(request, slug):
    brand=brand_for_request(request)
    data=VENTURE_PAGES.get(slug)
    if not brand or brand.code!="mojplaywin" or not data: raise Http404
    return render(request,"brands/mojplaywin/page.html",{"brand":brand,"page":data,"page_key":"venture"})


def branded_game(request, slug):
    brand=brand_for_request(request)
    if not brand or brand.code!="mojplaywin" or slug!="first-realm": raise Http404
    return render(request,"brands/mojplaywin/game.html",{"brand":brand})


